/** 📏️ Counts every authored Energy cell with the independent physical SQLite engine. */
function energyPhysicalCensus(db:Database){
 expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);
 const tables=(db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all() as {name:string}[]).map(({name})=>{
  const columns=db.query("PRAGMA table_info("+name+")").all() as {name:string}[];
  const expression=columns.map(({name})=>{const column='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+column+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+column+" AS BLOB)) WHEN 'blob' THEN length("+column+") WHEN 'null' THEN 0 ELSE NULL END"}).join("+");
  const extent=db.query("SELECT COUNT(*) AS rows,COALESCE(SUM("+expression+"),0) AS bytes FROM "+name).get() as {rows:bigint;bytes:bigint};
  return {table:name,rows:Number(extent.rows),semanticBytes:Number(extent.bytes)};
 });
